file_editor: {"command": "create", "path": "/app/solution.py", "file_text": "import json
import re
from pathlib import Path


SECTION_RE = re.compile(r"^\[([^\]]+)\]\s*$")
CHOICE_RE = re.compile(r"^\s*(\d+)\.\s*(.*?)\s*->\s*(\S+)\s*$")
LINE_RE = re.compile(r"^\s*(?:([^:]+):\s*)?(.*?)\s*->\s*(\S+)\s*$")

TERMINAL_SENTINEL = "End"


def parse_script(text: str):
    sections = []
    current_name = None
    current_body = []
    for raw in text.splitlines():
        line = raw.rstrip()
        if not line.strip():
            continue
        m = SECTION_RE.match(line)
        if m:
            if current_name is not None:
                sections.append((current_name, current_body))
            current_name = m.group(1).strip()
            current_body = []
        else:
            if current_name is None:
                continue
            current_body.append(line)
    if current_name is not None:
        sections.append((current_name, current_body))

    nodes = []
    edges = []

    for name, body in sections:
        is_choice = bool(body) and all(CHOICE_RE.match(b) for b in body)
        if is_choice:
            nodes.append({
                "id": name,
                "text": "",
                "speaker": "",
                "type": "choice",
            })
            for b in body:
                m = CHOICE_RE.match(b)
                option_text = m.group(2).strip()
                target = m.group(3).strip()
                edges.append({
                    "from": name,
                    "to": target,
                    "text": option_text,
                })
        else:
            # treat as single line node; expect one line with Speaker: text -> Target
            speaker = ""
            node_text = ""
            target = None
            for b in body:
                m = LINE_RE.match(b)
                if not m:
                    continue
                sp = (m.group(1) or "").strip()
                tx = (m.group(2) or "").strip()
                tgt = m.group(3).strip()
                speaker = sp
                node_text = tx
                target = tgt
            nodes.append({
                "id": name,
                "text": node_text,
                "speaker": speaker,
                "type": "line",
            })
            if target is not None:
                edges.append({
                    "from": name,
                    "to": target,
                    "text": "",
                })

    return {"nodes": nodes, "edges": edges}


def to_dot(graph) -> str:
    lines = ["digraph G {"]
    lines.append('  rankdir=LR;')
    lines.append('  node [shape=box];')
    node_ids = {n["id"] for n in graph["nodes"]}
    edge_targets = {e["to"] for e in graph["edges"]}
    terminals = edge_targets - node_ids
    for n in graph["nodes"]:
        label = n["id"]
        if n.get("speaker"):
            label += f'\\n{n["speaker"]}: {n["text"]}'
        elif n.get("text"):
            label += f'\\n{n["text"]}'
        shape = "diamond" if n["type"] == "choice" else "box"
        label_escaped = label.replace('"', '\\"')
        lines.append(f'  "{n["id"]}" [label="{label_escaped}", shape={shape}];')
    for t in sorted(terminals):
        lines.append(f'  "{t}" [label="{t}", shape=ellipse, style=filled, fillcolor=lightgray];')
    for e in graph["edges"]:
        et = e.get("text", "").replace('"', '\\"')
        lines.append(f'  "{e["from"]}" -> "{e["to"]}" [label="{et}"];')
    lines.append("}")
    return "\n".join(lines)


def validate(graph, first_id: str):
    assert isinstance(graph, dict)
    assert "nodes" in graph and "edges" in graph
    node_ids = set()
    for n in graph["nodes"]:
        for k in ("id", "text", "speaker", "type"):
            assert k in n, f"node missing {k}: {n}"
        assert n["type"] in ("line", "choice")
        node_ids.add(n["id"])

    for e in graph["edges"]:
        for k in ("from", "to", "text"):
            assert k in e, f"edge missing {k}: {e}"
        assert e["from"] in node_ids, f"edge from unknown: {e}"
        assert e["to"] in node_ids or e["to"] == TERMINAL_SENTINEL, \
            f"edge to unknown: {e}"

    # Reachability from first node
    adj = {}
    for e in graph["edges"]:
        adj.setdefault(e["from"], []).append(e["to"])
    seen = set()
    stack = [first_id]
    while stack:
        cur = stack.pop()
        if cur in seen:
            continue
        seen.add(cur)
        for nxt in adj.get(cur, []):
            if nxt not in seen:
                stack.append(nxt)
    unreachable = node_ids - seen
    assert not unreachable, f"unreachable nodes: {unreachable}"
    print("schema OK")


def main():
    script_path = Path("/app/script.txt")
    json_path = Path("/app/dialogue.json")
    dot_path = Path("/app/dialogue.dot")

    text = script_path.read_text()
    graph = parse_script(text)

    first_id = graph["nodes"][0]["id"] if graph["nodes"] else None

    with json_path.open("w") as f:
        json.dump(graph, f, indent=2)
    dot_path.write_text(to_dot(graph))

    # Post-write validation
    with json_path.open() as f:
        reloaded = json.load(f)
    validate(reloaded, first_id)
    assert dot_path.exists()
    assert dot_path.read_text().startswith("digraph")


if __name__ == "__main__":
    main()
